import{_ as e,o as l,c as t,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Orchestrator Meeting 2021-05-25","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2021-05-25","date":"2021-05-25T00:00:00.000Z","updated":"2021-05-26T00:00:00.000Z","tags":["Ceph","Orchestrator","Etsy Hosts","Ganesha","NFS EdgeRW"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-05-25.md","filePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-05-25.md","lastUpdated":1780460162000}'),r={name:"posts/2021/Ceph_Orchestrator_Meeting_2021-05-25.md"};function s(o,a,h,n,d,c){return l(),t("div",null,[...a[0]||(a[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-orchestrator-会议" tabindex="-1">会议主题：Orchestrator 会议 <a class="header-anchor" href="#会议主题-orchestrator-会议" aria-label="Permalink to &quot;会议主题：Orchestrator 会议&quot;">​</a></h4><h4 id="日期-2021-05-25" tabindex="-1">日期：2021-05-25 <a class="header-anchor" href="#日期-2021-05-25" aria-label="Permalink to &quot;日期：2021-05-25&quot;">​</a></h4><h4 id="参会人员-具体人员名单" tabindex="-1">参会人员：[具体人员名单] <a class="header-anchor" href="#参会人员-具体人员名单" aria-label="Permalink to &quot;参会人员：[具体人员名单]&quot;">​</a></h4><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><p><strong>Etsy Hosts 问题</strong></p><ul><li>讨论了 Etsy Hosts 文件的回归问题，涉及 DeepSea、Ansible 和 Cephadm Octopus Tana。</li><li>确认了两个相关的 Pull Request。</li><li>讨论了 Podman 和 Docker 的行为差异，特别是关于 get fqdn 的处理。</li><li>发现 Podman 在特定配置下返回回环地址，导致配置文件生成问题。</li><li>讨论了如何处理 DNS 和 Etsy Hosts 的依赖问题，建议在添加主机时强制指定 IP 地址。</li><li>提出在文档中明确说明使用 IP 地址的必要性，并更新相关代码以支持这一变化。</li></ul></li><li><p><strong>Ganesha 模板冲突问题</strong></p><ul><li>讨论了 Ganesha 模板中的冲突标志问题，该问题导致 NFS EdgeRW 损坏。</li><li>确认了需要移除 dirt chunk equal zero 配置。</li><li>讨论了是否应该使用单一 Ganesha 实例同时支持 CephFS 和 RGW 导出。</li><li>发现不同后端（CephFS 和 RGW）需要不同的配置选项，建议恢复为使用不同的 Ganesha 集群。</li><li>讨论了未来可能的改进方向，包括与 Ganesha 开发者的进一步沟通。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ol><li><p><strong>Etsy Hosts 问题</strong></p><ul><li>关闭第一个 Etsy Hosts 相关的 Pull Request。</li><li>更新文档，明确说明在添加主机时必须指定 IP 地址。</li><li>确保 <code>cephadm</code> 命令在添加主机时返回使用的 IP 地址。</li><li>进行代码审查，确保所有对 resolve ip 的调用都被正确处理。</li></ul></li><li><p><strong>Ganesha 模板冲突问题</strong></p><ul><li>暂时放弃使用单一 Ganesha 实例同时支持 CephFS 和 RGW 导出的方案。</li><li>恢复为使用不同的 Ganesha 集群，分别支持 CephFS 和 RGW。</li><li>等待与 Ganesha 开发者的进一步沟通，以确定最佳解决方案。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ol><li><p><strong>Etsy Hosts 问题</strong></p><ul><li>完成文档更新，明确说明使用 IP 地址的必要性。</li><li>更新 <code>cephadm</code> 命令，确保在添加主机时返回使用的 IP 地址。</li><li>进行代码审查，确保所有对 resolve ip 的调用都被正确处理。</li></ul></li><li><p><strong>Ganesha 模板冲突问题</strong></p><ul><li>与 Ganesha 开发者沟通，了解 dirt chunk 配置的具体影响。</li><li>根据沟通结果，确定是否需要进一步的配置调整或代码修改。</li><li>更新相关文档和代码，确保用户明确不同后端需要不同的 Ganesha 配置。</li></ul></li></ol><h4 id="其他讨论" tabindex="-1">其他讨论： <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论：&quot;">​</a></h4><ul><li>讨论了 Ingress 服务在底层 RGW 服务被删除时的行为，建议保持当前的异常处理方式，避免自动删除服务。</li></ul><h4 id="会议总结" tabindex="-1">会议总结： <a class="header-anchor" href="#会议总结" aria-label="Permalink to &quot;会议总结：&quot;">​</a></h4><p>本次会议主要解决了 Etsy Hosts 文件的回归问题和 Ganesha 模板冲突问题，明确了后续的行动计划和改进方向。通过与 Ganesha 开发者的进一步沟通，将有助于确定最佳的技术方案。</p>',14)])])}const _=e(r,[["render",s]]);export{u as __pageData,_ as default};
